sealed class CoverUpdate {
    
    object Keep : CoverUpdate()
    
    
    object Remove : CoverUpdate()
    
    
    data class Replace(
        val `image`: com.lyricsadapter.audiotags.CoverImage) : CoverUpdate()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCoverUpdate : FfiConverterRustBuffer<CoverUpdate>{
    override fun read(buf: ByteBuffer): CoverUpdate {
        return when(buf.getInt()) {
            1 -> CoverUpdate.Keep
            2 -> CoverUpdate.Remove
            3 -> CoverUpdate.Replace(
                FfiConverterTypeCoverImage.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoverUpdate): ULong = when(value) {
        is CoverUpdate.Keep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CoverUpdate.Remove -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CoverUpdate.Replace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCoverImage.allocationSize(value.`image`)
            )
        }
    }

    override fun write(value: CoverUpdate, buf: ByteBuffer) {
        when(value) {
            is CoverUpdate.Keep -> {
                buf.putInt(1)
                Unit
            }
            is CoverUpdate.Remove -> {
                buf.putInt(2)
                Unit
            }
            is CoverUpdate.Replace -> {
                buf.putInt(3)
                FfiConverterTypeCoverImage.write(value.`image`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Flat, so Kotlin exceptions carry the Display text as their message.
 */
sealed class TagException(message: String): kotlin.Exception(message) {
        
        class Io(message: String) : TagException(message)
        
        class Unsupported(message: String) : TagException(message)
        
        class Malformed(message: String) : TagException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TagException> {
        override fun lift(error_buf: RustBuffer.ByValue): TagException = FfiConverterTypeTagError.lift(error_buf)
    }
}

