            2 -> TagException.Unsupported(FfiConverterString.read(buf))
            3 -> TagException.Malformed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: TagException): ULong {
        return 4UL
    }

    override fun write(value: TagException, buf: ByteBuffer) {
        when(value) {
