            }
            is TagException.Unsupported -> {
                buf.putInt(2)
                Unit
            }
            is TagException.Malformed -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




